"""Beginner explanations for asm limits and pointer metadata types."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1769': ('정해진 크기를 넘으면 다른 크기로 바꾸는 규칙이 있어요. 얼마나 줄일지는 이름으로 짐작하지 말고 코드에 적힌 숫자를 확인해 봐요.', '어셈블리 출력 길이의 경계와 대체값을 구별합니다.', '4095, 4096, 4097 세 수 옆에 뒤로 전달될 길이를 각각 적어 보세요.', ['어셈블리 출력 도우미는 CPU 명령이 쓴 것으로 취급할 범위의 검사표를 준비됨으로 바꿔요. size는 그 범위의 바이트 수예요. 검사표를 바꾸는 것과 실제 데이터에 값을 쓰는 것은 다른 작업이에요.', '먼저 KMSAN이 켜져 있어야 아래 코드로 내려가요. 사용자 접근 상태를 저장한 뒤 size > 4096을 검사해요. >는 초과예요. 따라서 4096은 이 조건에 걸리지 않고 4097부터 걸려요.', '조건에 걸리면 WARN_ONCE로 경고해요. 경고 뒤 실행이 계속되면 size = 8을 실행해요. 4096으로 줄이는 것이 아니라 아예 대체값 8을 넣는 코드예요. 경고 설정에 따라 실행이 중단될 수 있으므로 계속되는 경우를 기준으로 읽어요.', '주소 분류도 통과한다고 가정하면 4095는 4095, 4096은 4096, 4097은 8이 unpoison 길이로 전달돼요. unpoison은 검사 상태를 준비됨으로 바꾸라는 요청이에요. 4097바이트를 모두 읽어 검사하는 명령이 아니에요.', '원문 주석은 대부분의 접근이 32바이트보다 작고, 알려진 예외로 64·512·4096바이트를 들고 있어요. 이 주석은 코드의 배경을 설명하지만, 조건에 걸린 값을 4096으로 바꾸라는 지시는 아니에요. 실제 대입문의 숫자를 확인해야 해요.', '검사 표시가 8바이트에 적용됐다고 원래 큰 범위 전체가 초기화됐다고 결론 내릴 수는 없어요. 또한 주소가 처리 대상에서 제외되면 unpoison 자체를 하지 않아요. 길이 조정과 주소 검사, 실제 데이터 상태를 각각 구분하세요.'], [('KMSAN이 켜져 있고 주소도 통과해요. size가 4097이고 경고 뒤 계속 실행된다면 unpoison 길이는 얼마인가요?', ['4096바이트예요', '8바이트예요'], '정답은 두 번째예요. size > 4096 분기에서 size = 8을 실행해요. 경계값으로 줄일 것이라는 추측보다 실제 대입문을 따라가세요.'), ('8바이트에 검사 표시를 바꾸면 원래 4097바이트 전체가 초기화됐다고 확인한 것인가요?', ['아니요. 대체 길이의 검사 정보를 처리한 것이에요', '네. 원래 범위를 전부 읽어서 검증한 것이에요'], '정답은 첫 번째예요. 실제 데이터 전체를 읽는 코드가 아니며 전달 길이도 8로 바뀌어요. 검사 표시 정책과 전체 데이터의 안전성 증명을 구별하세요.')]), 'os1770': ('다른 검사에서 잠깐 멈추는 규칙이 있어도, 꼭 기록해야 하는 사건은 따로 처리할 수 있어요. 함수마다 조건이 같은지 직접 확인해 봐요.', '어셈블리 검사 도우미의 runtime 조건과 접근 상태 복구를 이해합니다.', '꺼짐 경로, 제외 주소 경로, 정상 경로를 그리고 save와 restore가 있는 위치를 짝지어 보세요.', ['IRQ는 장치나 타이머 같은 사건을 CPU에 알리는 인터럽트 요청이에요. 커널은 그 일을 처리하러 들어갔다가 원래 흐름으로 돌아와요. 그 진입·종료 과정에서도 어셈블리 코드가 메모리에 값을 쓸 수 있어요.', '__msan_instrument_asm_store 위의 주석은 이런 쓰기도 준비됨으로 표시하려고 kmsan_in_runtime 검사를 생략한다고 설명해요. runtime은 KMSAN 자신의 일을 처리 중인 상태예요. 다른 검사 함수의 중단 조건을 여기에 그대로 적용하지 않아요.', '이 함수가 아무 조건 없이 항상 실행되는 것은 아니에요. 맨 앞에서 kmsan_enabled가 꺼져 있으면 끝나요. 이때는 아직 user_access_save를 호출하지 않았으므로 그 저장값을 복구하는 단계도 없어요.', '검사가 켜져 있으면 user_access_save의 결과를 ua_flags에 보관해요. 그다음 길이를 살피고 is_bad_asm_addr로 주소를 분류해요. 제외할 주소라면 user_access_restore(ua_flags)를 먼저 호출하고 돌아가요.', '처리할 주소이면 unpoison으로 검사표를 준비됨 상태로 바꾼 뒤 같은 ua_flags로 복구해요. 그러므로 정상 반환하는 두 경로에서 저장한 상태가 짝을 이뤄 복구되는지 따로 확인할 수 있어요.', 'runtime 상태가 1이라는 이유만으로 이 함수가 시작하자마자 돌아가는 코드는 없어요. 다만 실제 표시 여부는 활성 상태와 주소 등의 조건에도 달려 있어요. 이 원문 읽기는 실제 인터럽트를 발생시키거나 모든 호출 상황의 안전성을 검증한 실험은 아니에요.'], [('이 함수는 runtime 상태가 1이면 그것만을 이유로 맨 앞에서 끝내나요?', ['네. 모든 KMSAN 함수가 같은 조건으로 끝나요', '아니요. 여기에는 in_runtime 검사가 없어요'], '정답은 두 번째예요. IRQ 진입·종료 때의 출력도 표시하려는 이유가 주석에 있어요. 활성 여부와 주소를 살피는 다른 조건은 남아 있어요.'), ('주소가 제외 대상으로 분류돼 일찍 돌아갈 때도 저장한 접근 상태를 복구하나요?', ['네. return 바로 앞에 restore가 있어요', '아니요. 정상 처리했을 때만 복구해요'], '정답은 첫 번째예요. 제외 주소 분기 안에도 user_access_restore(ua_flags)가 있어요. 조기 반환 경로를 따로 따라가면 이 호출을 찾을 수 있어요.')]), 'os1771': ('상자에 붙은 위치 쪽지와 상자 안 물건의 준비 상태는 달라요. 위치 쪽지를 되돌려줄 때는 쪽지 자체에 붙은 검사 정보도 따로 전달해야 해요.', '포인터 값의 검사 정보와 버퍼 내용의 검사 정보를 구별합니다.', 'dst라는 주소 쪽지와 dst가 가리키는 데이터 칸들을 따로 그린 뒤 param0 → retval 화살표를 쪽지에 붙이세요.', ['memcpy는 복사, memmove는 겹치는 범위도 고려한 이동, memset은 같은 바이트 값으로 채우기예요. 이 함수들은 작업 뒤 도착 주소 dst를 반환해요. 반환값은 버퍼 전체 내용이 아니라 시작 위치를 가리키는 포인터예요.', '포인터 값 자체에도 초기화 상태가 있고 그 포인터가 가리키는 데이터 각 바이트에도 초기화 상태가 있어요. 주소 쪽지의 숫자가 준비됐는지와 상자 속 물건들이 준비됐는지는 서로 다른 질문이에요.', 'get_param0_metadata는 첫 번째 인자인 dst 포인터에 관한 검사 정보를 읽어요. param0의 0은 첫 번째 인자를 뜻해요. shadow는 그 값의 준비 상태, origin은 그와 관련된 원인 정보를 나타내요.', '세 wrapper는 실제 __memcpy, __memmove, __memset을 부르기 전에 이 정보를 지역 변수에 저장해요. wrapper는 다른 함수를 감싸며 추가 작업을 하는 함수예요. 먼저 저장해 둔 값은 뒤의 반환값 검사 정보 설정에 사용돼요.', '검사 처리를 끝까지 수행하는 경로에서는 set_retval_metadata(shadow, origin)으로 반환값용 공간에 저장해요. retval은 반환값이라는 뜻이에요. dst를 반환하므로 dst 포인터에 관한 정보를 연결하려는 흐름이에요. 중간의 조기 반환 경로는 이 설정을 건너뛸 수 있어요.', '이때 버퍼 전체의 shadow를 반환값 공간에 복사하는 것은 아니에요. 버퍼 내용의 검사 정보는 별도 처리 함수가 맡아요. 또한 origin을 실제로 몇 바이트 읽는지는 선언과 표현식을 확인해야 해요. 다음 수업에서는 고정 원문의 char 배열 읽기를 자세히 살펴봐요.'], [('이 반환값용 검사 정보가 나타내려는 대상은 무엇인가요?', ['도착 버퍼 안의 모든 데이터 바이트예요', '반환되는 dst 포인터 값 자체예요'], '정답은 두 번째예요. 함수는 dst 주소를 반환해요. 따라서 첫 인자인 dst 값의 검사 정보를 반환값에 연결하려는 것이며, 버퍼 전체의 상태와는 별개예요.'), ('첫 인자의 검사 정보는 실제 복사·채우기 함수 호출보다 먼저 읽나요?', ['네. get_param0_metadata가 먼저 있어요', '아니요. 작업 뒤 원본 버퍼에서 새로 계산해요'], '정답은 첫 번째예요. 세 wrapper 모두 실제 작업 앞에서 shadow와 origin을 받아 둬요. 전달 순서는 본문의 호출 위치로 확인할 수 있어요.')]), 'os1772': ('네 칸짜리 번호를 기대해도 코드가 첫 칸만 읽으면 나머지 칸은 합쳐지지 않아요. 값을 담을 통의 크기보다 실제 읽는 식을 먼저 봐야 해요.', 'char 한 바이트 읽기와 부호에 따른 숫자 변환을 이해합니다.', '첫 바이트 AB를 십진수 171로 쓰고, 부호 있는 경우의 -85와 u32 변환 결과를 계산해 보세요.', ['이 수업은 고정된 Linux v6.12의 실제 선언을 함께 읽어요. param_origin_tls는 char 배열이에요. char는 여기서 한 바이트짜리 칸이에요. param_origin_tls[0]은 그 배열의 첫 번째 칸 하나를 읽는 표현식이에요.', '읽은 값을 받을 depot_stack_handle_t는 u32예요. u32는 음수가 없는 32비트 정수이며 여기서는 4바이트예요. 받을 통이 4바이트라고 해서 첫 칸 읽기가 자동으로 네 칸 읽기로 바뀌지는 않아요.', '바로 위의 shadow 식은 u64 포인터로 형식을 바꿔 읽지만 origin 식에는 그런 형식 변환이 없어요. 뒤에 세 바이트가 더 있어도 [0]은 첫 char만 선택해요. 의도한 역할과 실제로 적힌 읽기 방법을 나누어 확인하세요.', 'AB는 16진수 숫자예요. A는 10, B는 11이므로 10 × 16 + 11 = 171이에요. 이 바이트를 unsigned char처럼 음수 없이 해석하면 171이고, 8비트 signed char처럼 부호 있게 해석하면 171 - 256 = -85예요.', '171을 u32에 넣으면 그대로 171이에요. -85를 u32로 바꾸면 2의 32승을 더한 4294967296 - 85 = 4294967211이 돼요. 이는 음수를 담을 수 없는 정수형으로 바꾸는 규칙 때문이에요. 큰 숫자를 외우기보다 계산 순서를 따라가세요.', 'plain char의 부호 성질은 컴파일 환경에 따라 달라질 수 있어요. 그래서 모든 환경에서 결과가 같다고 말하면 안 돼요. 이 원문을 읽은 결과를 모든 최신 커널에서 원인 번호를 이렇게 읽어야 한다는 권장 규칙으로 일반화하지도 마세요.'], [('param_origin_tls가 char 배열일 때 param_origin_tls[0]은 몇 칸을 읽나요?', ['u32에 넣으므로 자동으로 네 바이트를 읽어요', '첫 char 한 바이트를 읽어요'], '정답은 두 번째예요. [0]은 첫 요소 하나를 선택해요. 나중에 u32로 바꾸는 일은 배열의 나머지 세 칸을 읽는 일과 달라요.'), ('AB 바이트를 부호 있는 char와 없는 char로 해석한 뒤 u32로 바꾸면 같나요?', ['아니요. 각각 4294967211과 171이에요', '네. char는 언제나 음수가 없어요'], '정답은 첫 번째예요. 부호 있는 8비트 해석에서는 -85이고 이를 u32로 바꾸면 4294967211이에요. 부호 없는 해석의 171은 그대로 유지돼요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_438.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
